// flightCostModel.ts — CANONICAL SINGLE SOURCE OF TRUTH for what one drone
// flight-hour costs. This file lives here, in the simulation repo, next to the
// physics that produces the flight hours. The marketing website consumes a
// byte-identical VENDORED COPY of this file (photonicinsecticides-website
// src/lib/flightCostModel.ts, regenerated by its scripts/sync-flight-cost.mjs).
// Edit here, never there.
//
// The pricing pipeline is deliberately two layers, each independently verifiable:
//   1. PHYSICS  (src/sim/engine.ts) turns pest pressure / a target grid into
//      flight HOURS. Cross-checked by the closed-form src/sim/hoppingModel.ts
//      (see scripts/verifyHopping.ts).
//   2. PRICING  (this file) turns flight hours into $/ha at stated unit costs.
//      scripts/costSweep.ts prices the simulated flight hours through this model,
//      so the published dataset — and therefore the website — is reproducible by
//      running the sweep in this one repo.
//
// Three deliberately distinct outputs (do NOT collapse them):
//   1. marginalFlightCostPerHour        — costs that exist BECAUSE the drone flies:
//        battery cycle depreciation + charging electricity + flight-dependent wear.
//   2. ordinaryDroneCostPerHour         — marginal + capital ALLOCATION of the
//        airframe/electronics and shared charger. Capital allocation is an
//        accounting spread of purchase price over expected utilisation, not
//        physical per-hour wear.
//   3. fullyAllocatedSystemCostPerHour  — ordinary + the specialised optical/laser
//        payload, kept visible as its own line so reviewers can separate ordinary
//        drone economics from the pest-control equipment.
//
// Units used internally throughout: EUR, W, Wh, kWh, hours, years, efficiencies
// as decimal fractions (0..1). The site treats USD ≈ EUR at this scale (documented
// on the cart comparison); the sim dataset is USD-denominated.
//
// Calibration note (defaults): the "site baseline" scenario reproduces the
// laser_drone_sim cost model exactly (sim/defaults.ts: battery 140 Wh · 400
// cycles · €180, charger eff 0.9, electricity €0.15/kWh, maintenance €1/h,
// airframe €1,800 over 1,500 flight-h, laser €6,000 over 10,000 flight-h).
// averagePowerW = 253 W is the sweep dataset's mission-average electrical power
// for the 2.2 kg drone (reverse-derived: dataset battery $/ha ÷ flight-h matches
// €180×253/(140×400) = €0.813/h to <1%). The physics stays in the sim — this
// module only prices its flight hours.

export interface DroneFlightCostInputs {
  // battery
  batteryPriceEur: number;        // € per pack
  batteryCapacityWh: number;      // usable Wh per full cycle
  batteryCycleLife: number;       // full-equivalent cycles until replacement
  averagePowerW: number;          // mean electrical draw while operating, W
  chargingEfficiency: number;     // 0..1 — wall-to-battery
  // energy
  electricityPricePerKwh: number; // €/kWh at the wall
  // flight-dependent maintenance
  propellerPerHour: number;       // €/flight-h — props & minor parts
  motorBearingPerHour: number;    // €/flight-h — motors & bearings
  additionalMaintenancePerHour: number; // €/flight-h — optional extra allowance
  // drone capital (airframe + electronics, excl. batteries)
  dronePurchasePriceEur: number;
  droneWriteOffYears: number;
  droneOperatingHoursPerYear: number;
  droneResidualValueEur: number;
  /** Years the airframe physically OUTLIVES its accounting write-off. A flight hour
   * doesn't consume the airframe — so if it lasts beyond the write-off period, the
   * one-time cost spreads over the longer real life and the per-hour capital drops
   * (toward the marginal rate once fully paid off). 0 = dies at write-off. */
  droneOutliveWriteOffYears: number;
  // shared equipment (controller + charger, split across a fleet)
  chargerPurchasePriceEur: number;
  chargerWriteOffYears: number;
  chargerSharedDrones: number;          // drones sharing one controller/charger
  chargerAnnualHoursPerDrone: number;   // utilisation of each sharing drone, h/yr
  // optical / laser payload (allocated per flight hour, as the sim already does)
  opticalPurchasePriceEur: number;
  opticalLifetimeHours: number;
  opticalResidualValueEur: number;
}

export interface DroneFlightCostResult {
  // intermediates (exposed so the UI can show substituted formulas)
  batteryLifetimeEnergyWh: number;   // capacity × cycles
  energyPerFlightHourWh: number;     // averagePowerW × 1 h
  gridEnergyPerHourKwh: number;      // power / efficiency / 1000
  droneDepreciableValueEur: number;  // purchase − residual
  droneLifetimeHours: number;        // writeOffYears × hours/yr
  // per-hour components
  batteryDepreciationPerHour: number;
  electricityCostPerHour: number;
  maintenanceCostPerHour: number;
  droneCapitalCostPerHour: number;
  sharedEquipmentCostPerHour: number;
  opticalCapitalCostPerHour: number;
  // the three headline outputs
  marginalFlightCostPerHour: number;
  ordinaryDroneCostPerHour: number;
  fullyAllocatedSystemCostPerHour: number;
  /** human-readable validation problems; when non-empty the affected components are 0 */
  errors: string[];
}

const bad = (n: number) => !Number.isFinite(n) || Number.isNaN(n);

export function calculateDroneFlightHourCost(i: DroneFlightCostInputs): DroneFlightCostResult {
  const errors: string[] = [];
  const check = (cond: boolean, msg: string) => { if (cond) errors.push(msg); return cond; };

  // ---- validation (each failure zeroes only its own component, visibly) ----
  const numsOk = !check(Object.values(i).some((v) => typeof v !== "number" || bad(v)),
    "One or more inputs are not valid numbers.");
  const negOk = !check(numsOk && Object.values(i).some((v) => v < 0),
    "Costs, capacities and periods cannot be negative.");
  const ok = numsOk && negOk;

  const battOk = ok && !check(i.batteryCapacityWh <= 0 || i.batteryCycleLife <= 0,
    "Battery capacity and cycle life must be greater than zero.");
  const effOk = ok && !check(i.chargingEfficiency <= 0 || i.chargingEfficiency > 1,
    "Charging efficiency must be between 0 and 1 (e.g. 0.9 = 90%).");
  const droneUtilOk = ok && !check(i.droneWriteOffYears <= 0 || i.droneOperatingHoursPerYear <= 0,
    "Drone write-off period and operating hours per year must be greater than zero.");
  const droneResOk = ok && !check(i.droneResidualValueEur > i.dronePurchasePriceEur,
    "Drone residual value cannot exceed its purchase price.");
  const chargerOk = ok && (i.chargerPurchasePriceEur === 0 ||
    !check(i.chargerWriteOffYears <= 0 || i.chargerSharedDrones <= 0 || i.chargerAnnualHoursPerDrone <= 0,
      "Charger write-off period, shared-drone count and annual utilisation must be greater than zero."));
  const optOk = ok && (i.opticalPurchasePriceEur === 0 ||
    (!check(i.opticalLifetimeHours <= 0, "Optical-system lifetime hours must be greater than zero.") &&
     !check(i.opticalResidualValueEur > i.opticalPurchasePriceEur,
       "Optical residual value cannot exceed its purchase price.")));

  // ---- battery: € × Wh-used / lifetime-Wh ----
  const batteryLifetimeEnergyWh = battOk ? i.batteryCapacityWh * i.batteryCycleLife : 0;
  const energyPerFlightHourWh = ok ? i.averagePowerW * 1 : 0;
  const batteryDepreciationPerHour = battOk
    ? (i.batteryPriceEur * energyPerFlightHourWh) / batteryLifetimeEnergyWh : 0;

  // ---- electricity: wall energy incl. charging losses ----
  const gridEnergyPerHourKwh = effOk ? i.averagePowerW / i.chargingEfficiency / 1000 : 0;
  const electricityCostPerHour = effOk ? gridEnergyPerHourKwh * i.electricityPricePerKwh : 0;

  // ---- flight-dependent maintenance ----
  const maintenanceCostPerHour = ok
    ? i.propellerPerHour + i.motorBearingPerHour + i.additionalMaintenancePerHour : 0;

  // ---- drone capital: (price − residual) / (years × h/yr) — allocation, not wear ----
  const droneDepreciableValueEur = droneResOk ? Math.max(i.dronePurchasePriceEur - i.droneResidualValueEur, 0) : 0;
  // Amortize the one-time airframe over its REAL physical life = write-off period plus
  // any years it outlives that write-off. A durable drone spreads its cost over more
  // hours ⇒ lower €/flight-hour ⇒ lower €/ha.
  const droneRealLifeYears = i.droneWriteOffYears + Math.max(i.droneOutliveWriteOffYears, 0);
  const droneLifetimeHours = droneUtilOk ? droneRealLifeYears * i.droneOperatingHoursPerYear : 0;
  const droneCapitalCostPerHour = droneUtilOk && droneResOk && droneLifetimeHours > 0
    ? droneDepreciableValueEur / droneLifetimeHours : 0;

  // ---- shared charger/controller: (price / write-off yrs) / (drones × h/yr each) ----
  const sharedEquipmentCostPerHour = chargerOk && i.chargerPurchasePriceEur > 0
    ? (i.chargerPurchasePriceEur / i.chargerWriteOffYears) /
      (i.chargerSharedDrones * i.chargerAnnualHoursPerDrone)
    : 0;

  // ---- optical/laser payload: (price − residual) / lifetime flight-hours ----
  const opticalCapitalCostPerHour = optOk && i.opticalPurchasePriceEur > 0
    ? Math.max(i.opticalPurchasePriceEur - i.opticalResidualValueEur, 0) / i.opticalLifetimeHours
    : 0;

  const marginalFlightCostPerHour = batteryDepreciationPerHour + electricityCostPerHour + maintenanceCostPerHour;
  const ordinaryDroneCostPerHour = marginalFlightCostPerHour + droneCapitalCostPerHour + sharedEquipmentCostPerHour;
  const fullyAllocatedSystemCostPerHour = ordinaryDroneCostPerHour + opticalCapitalCostPerHour;

  return {
    batteryLifetimeEnergyWh, energyPerFlightHourWh, gridEnergyPerHourKwh,
    droneDepreciableValueEur, droneLifetimeHours,
    batteryDepreciationPerHour, electricityCostPerHour, maintenanceCostPerHour,
    droneCapitalCostPerHour, sharedEquipmentCostPerHour, opticalCapitalCostPerHour,
    marginalFlightCostPerHour, ordinaryDroneCostPerHour, fullyAllocatedSystemCostPerHour,
    errors,
  };
}

// ---------------------------------------------------------------------------
// Scenarios. "site-baseline" reproduces the published sim cost model exactly and
// is the default everywhere; the others are plausible, documented variations —
// not straw men. Any manual edit becomes "custom".
// ---------------------------------------------------------------------------

export type FlightCostScenarioId = "site-baseline" | "paper-small-drone" | "conservative" | "custom";

