// ---------------------------------------------------------------------------
// Derived rate bundles for the dependent simulations. Each sim picks the
// economically appropriate output — do NOT feed every sim the same total.
// ---------------------------------------------------------------------------

/** Rates for a SCOUT drone: camera payload, no laser → marginal + drone capital
 * + shared charger, EXCLUDING the optical allocation. */
export function scoutCostPerFlightHour(r: DroneFlightCostResult): number {
  return r.ordinaryDroneCostPerHour;
}

/** Rates for the SHOOTING drone (carries the laser) → fully allocated. */
export function shootingCostPerFlightHour(r: DroneFlightCostResult): number {
  return r.fullyAllocatedSystemCostPerHour;
}

/** Price a simulated mission: the sweep dataset supplies the PHYSICS (flight hours
 * per sweep over `fieldHa`); this shared model supplies the ECONOMICS. Component
 * split mirrors the cost chart's checkboxes: "amortization" = capital allocations
 * (drone + charger + laser) + flight-dependent maintenance; battery and
 * electricity are separate. All €/ha for ONE sweep. */
export function priceFlightHoursPerHa(flightHours: number, fieldHa: number, r: DroneFlightCostResult) {
  const ha = Math.max(fieldHa, 1e-9);
  return {
    amortization: (flightHours * (r.droneCapitalCostPerHour + r.sharedEquipmentCostPerHour +
      r.opticalCapitalCostPerHour + r.maintenanceCostPerHour)) / ha,
    battery: (flightHours * r.batteryDepreciationPerHour) / ha,
    electricity: (flightHours * r.electricityCostPerHour) / ha,
  };
}
